from __future__ import annotations

import base64
from pathlib import Path

REPO_ROOT = Path.cwd()
SERVER = REPO_ROOT / "src" / "aicognitive_mind" / "mcp_server.py"
CAPABILITY = REPO_ROOT / "src" / "aicognitive_mind" / "github_capability.py"
CAPABILITY_B64 = ""
TOOLS_B64 = ""


def fail(message: str) -> None:
    raise SystemExit(f"ERROR: {message}")


if not SERVER.exists():
    fail(f"Run this from the AICognitiveMind repository root. Missing: {SERVER}")

CAPABILITY.write_bytes(base64.b64decode(CAPABILITY_B64))
tools_block = base64.b64decode(TOOLS_B64).decode("utf-8").strip()
server_text = SERVER.read_text(encoding="utf-8")

import_line = "from aicognitive_mind.github_capability import GitHubCapability\n"
if import_line not in server_text:
    anchor = "from aicognitive_mind.mcp_service import"
    if anchor not in server_text:
        fail(
            "Could not locate the mcp_service import in mcp_server.py. "
            "github_capability.py was created, but mcp_server.py was left unchanged."
        )
    server_text = server_text.replace(anchor, import_line + anchor, 1)

marker = "# --- Axiom GitHub capability"
if marker not in server_text:
    main_anchor = '\nif __name__ == "__main__":'
    if main_anchor in server_text:
        server_text = server_text.replace(
            main_anchor,
            "\n" + tools_block + "\n\n" + main_anchor,
            1,
        )
    else:
        server_text = server_text.rstrip() + "\n\n" + tools_block + "\n"

SERVER.write_text(server_text, encoding="utf-8")

print("Axiom GitHub capability installed.")
print("Added MCP tools: github_status, github_list_path, github_read_file, github_write_file")
print("Set deployment secrets:")
print("  AXIOM_GITHUB_TOKEN=<fine-grained GitHub token>")
print("  AXIOM_GITHUB_REPOSITORY=Moto1231/AICognitiveMind")
print("Then verify:")
print("  python -m compileall src/aicognitive_mind/github_capability.py src/aicognitive_mind/mcp_server.py")
